// === Tab: mySketch ===
const arrows = [];
const num_arrows= 1000;

let pointerX = 0;
let pointerY = 0;
const margin = 30;

// const color_array = [
//  	//red
//  	'255, 60, 60',
//  	//green
//  	'10, 215, 180',
//  	//blue 
//  	'50, 100, 255'
//  ];

const color_array = ['255,255,255'];

class Arrow {
  constructor(x, y){
    this.base = 5;
    this.length = 0;
		this.max_length = random(30, 100);
		this.trans_origin = 10;
		this.fill = random(color_array);
    // this.posX = random(this.length + margin, width - this.length - margin);
    // this.posY = random(this.length + margin, height - this.length - margin);
		this.posX = x;
		this.posY = y;
    this.position = createVector(this.posX, this.posY);
		// this.position = createVector(width/2,height/2);
    this.rotation = 0;
		this.velocity = createVector(random(-.15,.15), random(-.15,.15));
		// this.velocity = createVector(0, 0);
  }

  display() {
    push();
    translate(this.position.x, this.position.y);
    rotate(PI/2 + this.rotation);
		blendMode(SCREEN);
    fill(`rgba(${this.fill}, .25)`);
    noStroke();
    triangle(-this.base/2, this.trans_origin, 0, this.trans_origin - this.length, this.base/2, this.trans_origin);
		fill(`rgba(${this.fill}, 1)`);
		ellipse(0, this.trans_origin, this.base, this.base);
    pop();
  }
  update() {
		this.position.add(this.velocity);
  }
  fadeout() {

	}

	point(pointerX, pointerY) {
		// let transX = pointerX - this.posX;
    // let transY = pointerY - this.posY;
    // this.rotation = atan2(transY, transX);

    //VECTOR WAY OF DOING THINGS
		let pointer = createVector(pointerX, pointerY);
    let dir = pointer.sub(this.position);
		let mag = dir.mag();
		this.length = constrain(mag, 0, this.max_length);
    this.rotation = dir.heading();
	}

	edges() {
		if (this.position.x > width - margin || this.position.x < margin) {
			this.velocity.x *= -1;
		}
		if (this.position.y > height - margin || this.position.y < margin) {
			this.velocity.y *= -1;
		}
	}
}

function setup() {
  createCanvas(windowWidth, windowHeight);
  for (let i = 0; i < 0; i++) {
		let x = random(margin, width);
		let y = random(margin, height);
    arrows.push(new Arrow(x, y));
  }
}
function draw() {
  background(0);

  if (touches.length){
  	pointerX = touches[0].x;
  	pointerY = touches[0].y;
  } else if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) {
    pointerX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
    pointerY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
  } else {
    pointerX = 0;
    pointerY = 0;
  }

  for (let i = 0; i < arrows.length; i++) {
    arrows[i].display();
		arrows[i].update();
		arrows[i].edges();
    arrows[i].point(pointerX, pointerY);
  }
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && arrows.length < num_arrows) {
		arrows.push(new Arrow(pointerX, pointerY));
	}
	if (arrows.length >= num_arrows ) {
    arrows.splice(0,1);
  }
	fill(255);

	if(arrows.length === 0) {
		let msg = 'click to draw';
		let msg_width = textWidth(msg)
		textSize(30);
		text(msg, width/2 - msg_width/2, height/2);		
	}
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

